param([Parameter(Mandatory)][string]$ProjectRoot,[Parameter(Mandatory)][string]$BuildRoot)
$ErrorActionPreference='Stop';$ProjectRoot=[IO.Path]::GetFullPath($ProjectRoot);$BuildRoot=[IO.Path]::GetFullPath($BuildRoot);Add-Type -Path (Join-Path $PSScriptRoot PrivateDesktop.cs)
$root=Join-Path $ProjectRoot ('artifacts/circadian-planning-'+[Guid]::NewGuid().ToString('N'));New-Item -ItemType Directory -Force $root|Out-Null
$env:HIBERNATION_SESSION_KEY='circadian-planning-fixture';$service=$null;$provider=$null;$desktop=$null;$checks=0
function Check($Value,$Name){if(!$Value){throw "CHECK FAILED: $Name"};$script:checks++;Write-Output "PASS $Name"}
function Await([scriptblock]$Probe,$Name,[int]$Seconds=40){$until=[DateTime]::UtcNow.AddSeconds($Seconds);while([DateTime]::UtcNow-lt$until){if($service-and$service.HasExited){throw 'fixture_backend_exited'};if(& $Probe){return};Start-Sleep -Milliseconds 80};throw "TIMEOUT $Name"}
function Api($Path,$Data=$null){$args=@{Uri=$script:origin+$Path;Headers=@{Authorization='Bearer circadian-planning-fixture'};TimeoutSec=10};if($null-ne$Data){$args.Method='Post';$args.ContentType='application/json';$args.Body=[Text.Encoding]::UTF8.GetBytes(($Data|ConvertTo-Json -Depth 50 -Compress))};Invoke-RestMethod @args}
function Requests($Review=$false){$file=Join-Path $root $(if($Review){'provider/review-requests.jsonl'}else{'provider/requests.jsonl'});if(Test-Path -LiteralPath $file){return @(Get-Content -LiteralPath $file).Count};0}
function Auto($Enabled,$Master=$true){$settings=(Api '/api/dashboard').settings|ConvertTo-Json -Depth 60|ConvertFrom-Json -AsHashtable;$settings.plugins.widget.autonomousMode=$Enabled;$settings.plugins.rhythm.circadianEnabled=$Master;$null=Api '/api/settings' @{settings=$settings};if(!$Enabled){Await {!((Api '/api/activities/status').generating)} 'planner stopped'}}
function Plan($Proposal,$Verdict='approve'){
 @{nonce=[Guid]::NewGuid().ToString('N');responses=@(@{response=@{version=1;commands=@();circadian_routine=$Proposal}})}|ConvertTo-Json -Depth 30|Set-Content -LiteralPath (Join-Path $root provider/plan.json) -Encoding utf8NoBOM
 @{nonce=[Guid]::NewGuid().ToString('N');responses=@(@{response=@{decision=$Verdict;reason=$(if($Verdict-eq'approve'){'ok'}else{'other'});guidance=$(if($Verdict-eq'approve'){''}else{'synthetic rejection'})}})}|ConvertTo-Json -Depth 20|Set-Content -LiteralPath (Join-Path $root provider/review-plan.json) -Encoding utf8NoBOM
}
function Batch($Proposal,$Verdict='approve',$Master=$true,$ExpectedError=''){
 Auto $false;$previous=(Api '/api/activities/status').personal_carry_feedback.generation;$actor=Requests;$review=Requests $true;Plan $Proposal $Verdict;Auto $true $Master
 Await {(Requests)-gt$actor} 'actor plan';Await {$s=Api '/api/activities/status';!$s.generating-and$(if($ExpectedError){$s.last_error-eq$ExpectedError}else{$s.personal_carry_feedback.generation-and$s.personal_carry_feedback.generation-ne$previous})} 'proposal decision'
 $s=Api '/api/activities/status';Auto $false $Master;return @{status=$s;actor_calls=(Requests)-$actor;review_calls=(Requests $true)-$review}
}
function Observe{$null=Api '/api/plugin/test' @{tool='rhythm.observe';args=@{}};Await {$script:r=Api '/api/plugin/result';$script:r.state-in@('succeeded','failed')} observe;if(!$script:r.result.ok){throw 'observe_failed'};return $script:r.result.result.circadian}
try{
 $provider=Start-Process -FilePath (Join-Path $BuildRoot Hibernation_TestProvider.exe) -ArgumentList ('"'+$root+'/provider"') -WindowStyle Hidden -PassThru -RedirectStandardOutput (Join-Path $root provider.log) -RedirectStandardError (Join-Path $root provider-error.log)
 Await {Test-Path -LiteralPath (Join-Path $root provider/port)} provider;$fixture='http://127.0.0.1:'+(Get-Content -LiteralPath (Join-Path $root provider/port))
 $cfg=Get-Content -LiteralPath (Join-Path $ProjectRoot config/example.json) -Raw|ConvertFrom-Json -AsHashtable;$cfg.dataRoot=Join-Path $root data;$cfg.characterRoot=Join-Path $ProjectRoot character;$cfg.uiRoot=Join-Path $ProjectRoot ui;$cfg.pluginRoot=Join-Path $BuildRoot plugins;$cfg.frontend.startupAnimation=$false;$cfg.cognition=@{enabled=$true};$cfg.solitudeIntervalMs=604800000;$cfg.idleBeforeSolitudeMs=86400000;$cfg.reflectOnActivities=$false;$cfg.maxStartsPerHour=1000
 $cfg.plugins=@{widget=@{enabled=$true;skin='asterlan';animationMode='sequence';roam=$false;showBubble=$false;reactionCacheEnabled=$false;autonomousMode=$false;autonomyIdleSeconds=5;autonomyRefillSeconds=300};rhythm=@{enabled=$true;circadianEnabled=$true;automaticRest=$false;idleBeforeRestSeconds=5}}
 $cfg.profiles=@($cfg.profiles[0],@{id='actor';label='Synthetic routine actor';enabled=$true;protocol='chat-completions';origin=$fixture;model='fixture-model';supportsJsonObject=$true},@{id='reviewer';label='Synthetic routine reviewer';enabled=$true;protocol='chat-completions';origin=$fixture;model='fixture-reviewer';supportsJsonObject=$true});$cfg.review=@{enabled=$true;profileId='reviewer';maxRewrites=1}
 $config=Join-Path $root config.json;$ready=Join-Path $root ready.json;$cfg|ConvertTo-Json -Depth 40|Set-Content -LiteralPath $config -Encoding utf8NoBOM;$desktop=[PrivateDesktop]::new((Join-Path $BuildRoot hibernation-agent.exe),$config,$ready,$ProjectRoot);$service=$desktop.Child;Await {Test-Path -LiteralPath $ready} backend;$script:origin='http://127.0.0.1:'+((Get-Content -LiteralPath $ready -Raw|ConvertFrom-Json).port);$null=Api '/api/model' @{id='actor'}
 $m=(Get-Date).Hour*60+(Get-Date).Minute;$preferences=@{enabled=$true;start_minute=($m+120)%1440;end_minute=($m+480)%1440;drag_wake_probability=.2;message_wake_probability=.6;inertia_seconds=600};$proposal=@{expected_revision=0;preferences=$preferences}
 $result=Batch $proposal;Check ($result.actor_calls-eq1-and$result.review_calls-eq1) 'routine uses existing actor and reviewer once without a third connection'
 $feedback=$result.status.personal_carry_feedback.results|Where-Object tool -eq 'rhythm.configure';Check ($feedback.ok-and$feedback.revision-eq1-and(Observe).preferences_revision-eq1) 'reviewed background proposal reaches versioned routine state'
 $context=(Get-Content -LiteralPath (Join-Path $root provider/last-request.json) -Raw|ConvertFrom-Json -Depth 70).messages[1].content|ConvertFrom-Json -Depth 70;Check ($context.routine_configuration.available-and$context.routine_configuration.current.preferences_revision-eq0) 'actor discovers routine capability and current revision without user instruction'
 $result=Batch $proposal;$feedback=$result.status.personal_carry_feedback.results|Where-Object tool -eq 'rhythm.configure';Check (!$feedback.ok-and$feedback.error.code-eq'circadian_revision'-and(Observe).preferences_revision-eq1) 'stale approved proposal cannot overwrite a newer routine'
 $proposal.expected_revision=1;$result=Batch $proposal 'deny' $true 'activity_review_rejected';Check ((Observe).preferences_revision-eq1) 'review rejection leaves routine unchanged'
 $result=Batch $proposal 'approve' $false 'activity_circadian_unavailable';Check ($result.review_calls-eq0-and(Observe).preferences_revision-eq1) 'disabled capability rejects proposal before paying for review'
 $preferences.enabled=$false;$result=Batch $proposal;Check ((Observe).preferences_revision-eq2-and!(Observe).preferences.enabled) 'role can autonomously disable its own routine'
 Start-Sleep -Milliseconds 650;$audit=Api '/api/mind/trace';Check (@($audit.events|Where-Object kind -eq 'cognition.sleep.proposal').Count-ge3) 'accepted and stale proposals leave auditable outcomes'
 Check ((Api '/api/dashboard').health-eq'ok') 'native planning host remains healthy';$null=Api '/api/shutdown' @{};Check ($service.WaitForExit(10000)-and$service.ExitCode-eq0) 'planning host stops cleanly'
 @{completed=$true;checks=$checks;paid_model_calls=0;local_actor_requests=(Requests);local_review_requests=(Requests $true);root=$root}|ConvertTo-Json|Set-Content -LiteralPath (Join-Path $root acceptance.json) -Encoding utf8NoBOM;Write-Output "Evidence: $root"
}finally{if($service){$service.Refresh();if(!$service.HasExited){try{$null=Api '/api/shutdown' @{};$service.WaitForExit(5000)|Out-Null}catch{};$service.Refresh();if(!$service.HasExited){Stop-Process -Id $service.Id}}};if($desktop){$desktop.Dispose()};if($provider){$provider.Refresh();if(!$provider.HasExited){Stop-Process -Id $provider.Id}}}
